update known_safe_harbors set tissue_context = 'ESC/iPSC lines, including patient (Parkinson''s) and healthy-sibling-control iPSCs' where source_pmid = '24304893' and evidence_summary = 'FOUNDING PAPER of human H11: "we identified a novel human locus, H11, located in a safe, transcriptionally active intergenic region of chromosome 22" (confirms band 22q12.2 already on record via review). DICE system (dual cassette exchange via phiC31+Bxb1 integrases) with 100% specificity. Tested with mCherry and neural transcription factors (LMX1a, FOXA2, OTX2) in ESC/iPSC lines, including iPSC from a Parkinson''s patient and a healthy sibling control -- directly relevant to neuronal/dopaminergic differentiation.';
