update known_safe_harbors set tissue_context = 'Mouse liver, in vivo cancer model' where source_pmid = '32986839' and evidence_summary = 'Same Cas9-N57 system used to insert oncogenic KrasG12D at ROSA26 (plus disruption of Trp53/Pten) to induce intrahepatic cholangiocarcinoma in mice -- not a locus failure, it confirms that ROSA26 expresses an inserted oncogene reliably and on command, used deliberately as a cancer model. Relevant as proof of reliable, controllable expression, even if in a different application context.';
