update known_safe_harbors set tissue_context = 'Human T cells; humanized PBMC mouse model in vivo' where source_pmid = '36680242' and evidence_summary = 'Anti-HIV CAR (scFv from bNAb 10-1074) integrated at CCR5 in human T cells via CRISPR/Cas9. Specific lysis of HIV-infected cells in vitro. In a humanized PBMC mouse model, the CAR-T cells expanded and transiently limited HIV infection in vivo.';
update public_safe_harbors_staging set tissue_context = 'Human T cells; humanized PBMC mouse model in vivo' where source_pmid = '36680242' and evidence_summary = 'Anti-HIV CAR (scFv from bNAb 10-1074) integrated at CCR5 in human T cells via CRISPR/Cas9. Specific lysis of HIV-infected cells in vitro. In a humanized PBMC mouse model, the CAR-T cells expanded and transiently limited HIV infection in vivo.';

update known_safe_harbors set tissue_context = 'iPSCs, differentiated into hematopoietic cells including macrophages' where source_pmid = '26670276' and evidence_summary = 'Not transgene insertion, this is CCR5 disruption by CRISPR/Cas9 in iPSCs (12.5% editing with a single gRNA, rising to 27% with dual gRNA). iPSC lines homozygous for mutated CCR5 retained pluripotency characteristics and differentiated efficiently into hematopoietic cells, including macrophages. Edited macrophages were specifically resistant to CCR5-tropic virus, but not CXCR4-tropic virus -- confirms CCR5 loss is functionally well tolerated.';
update public_safe_harbors_staging set tissue_context = 'iPSCs, differentiated into hematopoietic cells including macrophages' where source_pmid = '26670276' and evidence_summary = 'Not transgene insertion, this is CCR5 disruption by CRISPR/Cas9 in iPSCs (12.5% editing with a single gRNA, rising to 27% with dual gRNA). iPSC lines homozygous for mutated CCR5 retained pluripotency characteristics and differentiated efficiently into hematopoietic cells, including macrophages. Edited macrophages were specifically resistant to CCR5-tropic virus, but not CXCR4-tropic virus -- confirms CCR5 loss is functionally well tolerated.';

update known_safe_harbors set tissue_context = 'Human peripheral blood T cells; in vivo mouse leukemia model' where source_pmid = '28225754' and evidence_summary = 'FOUNDING PAPER for using TRAC in CAR-T (Eyquem et al., highly cited). Anti-CD19 CAR directed to the TRAC locus (not random integration): uniform CAR expression in human peripheral blood T cells, increased potency vs. conventional CAR-T, with far superior performance in a mouse model of acute lymphoblastic leukemia. Avoids tonic CAR signaling, allows effective internalization/re-expression after repeated antigen exposure, delays effector T-cell differentiation and exhaustion.';
update public_safe_harbors_staging set tissue_context = 'Human peripheral blood T cells; in vivo mouse leukemia model' where source_pmid = '28225754' and evidence_summary = 'FOUNDING PAPER for using TRAC in CAR-T (Eyquem et al., highly cited). Anti-CD19 CAR directed to the TRAC locus (not random integration): uniform CAR expression in human peripheral blood T cells, increased potency vs. conventional CAR-T, with far superior performance in a mouse model of acute lymphoblastic leukemia. Avoids tonic CAR signaling, allows effective internalization/re-expression after repeated antigen exposure, delays effector T-cell differentiation and exhaustion.';

update known_safe_harbors set tissue_context = 'Human T cells; in vivo mouse tumor model' where source_pmid = '28237835' and evidence_summary = 'Anti-CD19 CAR inserted directly into the native TRAC locus via homing endonuclease + AAV donor template. Resulting cells do not express the endogenous TCR, show potent effector functions in vitro, and eliminate CD19+ tumors in a mouse model in vivo -- specifically designed for allogeneic production (avoids GvHD by eliminating the endogenous TCR through the insertion itself).';
update public_safe_harbors_staging set tissue_context = 'Human T cells; in vivo mouse tumor model' where source_pmid = '28237835' and evidence_summary = 'Anti-CD19 CAR inserted directly into the native TRAC locus via homing endonuclease + AAV donor template. Resulting cells do not express the endogenous TCR, show potent effector functions in vitro, and eliminate CD19+ tumors in a mouse model in vivo -- specifically designed for allogeneic production (avoids GvHD by eliminating the endogenous TCR through the insertion itself).';

update known_safe_harbors set tissue_context = 'Human T cells; mouse xenograft leukemia model' where source_pmid = '35573047' and evidence_summary = 'Virus-free editing method (CRISPR-Cas + double-stranded DNA template) optimized for CAR insertion at TRAC, combining DNA-sensor inhibition with HDR potentiation -- CAR knock-in rates at TRAC above 50% of cells. Resulting CAR-T cells showed antigen-specific cytotoxicity and cytokine production in vitro, and slowed leukemia progression in a mouse xenograft model. Amplicon sequencing revealed no significant indel formation at potential off-target sites.';
update public_safe_harbors_staging set tissue_context = 'Human T cells; mouse xenograft leukemia model' where source_pmid = '35573047' and evidence_summary = 'Virus-free editing method (CRISPR-Cas + double-stranded DNA template) optimized for CAR insertion at TRAC, combining DNA-sensor inhibition with HDR potentiation -- CAR knock-in rates at TRAC above 50% of cells. Resulting CAR-T cells showed antigen-specific cytotoxicity and cytokine production in vitro, and slowed leukemia progression in a mouse xenograft model. Amplicon sequencing revealed no significant indel formation at potential off-target sites.';

update known_safe_harbors set tissue_context = 'Jurkat T cells' where source_pmid = '27271519' and evidence_summary = 'CELiD (AAV-dependent) vector for CAR integration at AAVS1 in Jurkat cells: of 71 stably transfected clones tested, 30 contained the CAR gene within the AAVS1 site -- site-specific integration efficiency of 42.2%, quantified by nested PCR, sequencing, and Southern blot.';
