update known_safe_harbors set tissue_context = 'Mechanistic/structural study, not cell-type specific; open conformation also confirmed in transgenic mice' where source_pmid = '10906224' and evidence_summary = 'Founding mechanistic paper (2000), explains WHY AAVS1 works: the Rep binding site (RBS) within AAVS1 is located near a DNase-I-hypersensitive "open" chromatin region, with enhancer-like transcriptional properties -- a "transcriptionally competent environment" that explains the locus''s accessibility to integration and AAV Rep proteins. Open conformation also confirmed in transgenic mice carrying the AAVS1 fragment.';
update public_safe_harbors_staging set tissue_context = 'Mechanistic/structural study, not cell-type specific; open conformation also confirmed in transgenic mice' where source_pmid = '10906224' and evidence_summary = 'Founding mechanistic paper (2000), explains WHY AAVS1 works: the Rep binding site (RBS) within AAVS1 is located near a DNase-I-hypersensitive "open" chromatin region, with enhancer-like transcriptional properties -- a "transcriptionally competent environment" that explains the locus''s accessibility to integration and AAV Rep proteins. Open conformation also confirmed in transgenic mice carrying the AAVS1 fragment.';

update known_safe_harbors set tissue_context = 'Endogenous locus biology, not a specific cell type -- systemic metabolic effect (vitamin B12 pathway)' where source_pmid = '40108300' and evidence_summary = 'Important biological caveat (not transgene expression data, this is endogenous locus biology): CLYBL encodes a real enzyme with its own function -- it repairs malyl-CoA, a citric-acid-cycle byproduct, preventing inhibition of methylmalonyl-CoA mutase and vitamin B12 depletion. CLYBL knockout has a real, measurable metabolic consequence, though apparently tolerable in the safe-harbor studies already on record. Worth not treating CLYBL as "neutral" without qualification.';
update public_safe_harbors_staging set tissue_context = 'Endogenous locus biology, not a specific cell type -- systemic metabolic effect (vitamin B12 pathway)' where source_pmid = '40108300' and evidence_summary = 'Important biological caveat (not transgene expression data, this is endogenous locus biology): CLYBL encodes a real enzyme with its own function -- it repairs malyl-CoA, a citric-acid-cycle byproduct, preventing inhibition of methylmalonyl-CoA mutase and vitamin B12 depletion. CLYBL knockout has a real, measurable metabolic consequence, though apparently tolerable in the safe-harbor studies already on record. Worth not treating CLYBL as "neutral" without qualification.';

update known_safe_harbors set tissue_context = 'Human T cells (anti-GD2 CAR-T, neuroblastoma target)' where source_pmid = '40123742' and evidence_summary = 'Cas9-CLIPT system (circular plasmid linearized in vitro by Cas9-RNP itself) for non-viral insertion at TRAC: up to 60% precise knock-in efficiency with NHEJ inhibition, even with large transgenes (2-6kb). Resulting anti-GD2 CAR-T cells (neuroblastoma) were potent, with a phenotype enriched in stem-cell memory.';
