update known_safe_harbors set tissue_context = 'Real CAR-T patients, longitudinal in vivo follow-up (T cells)' where source_pmid = '39972592' and evidence_summary = 'Real longitudinal analysis in CAR-T patients: lentiviral integration concentrated in introns, with no major clonal proliferation after 1 year. Gammaretroviral integration concentrated in intergenic regions near transcription start sites -- divergent outcomes: one patient with no detectable CAR after 1 year, another with low-level oligoclonal persistence (future malignancy risk still unclear).';
update public_safe_harbors_staging set tissue_context = 'Real CAR-T patients, longitudinal in vivo follow-up (T cells)' where source_pmid = '39972592' and evidence_summary = 'Real longitudinal analysis in CAR-T patients: lentiviral integration concentrated in introns, with no major clonal proliferation after 1 year. Gammaretroviral integration concentrated in intergenic regions near transcription start sites -- divergent outcomes: one patient with no detectable CAR after 1 year, another with low-level oligoclonal persistence (future malignancy risk still unclear).';

update known_safe_harbors set tissue_context = 'Real patient cohort (449 patients), clinical follow-up -- T cells (CAR-T)' where source_pmid = '38266761' and evidence_summary = 'Real cohort of 449 patients treated with commercial CAR-T (CD19, BCMA): 3.6% developed a secondary malignancy at a median follow-up of 10.3 months; projected 5-year cumulative incidence of 15.2% (solid) and 2.3% (hematologic). Only 1 case of T-cell lymphoma effectively linked to the CAR (low transgene levels, pre-existing clone before infusion) -- authors'' conclusion: low risk of T-cell lymphoma attributable to CAR-T itself.';
update public_safe_harbors_staging set tissue_context = 'Real patient cohort (449 patients), clinical follow-up -- T cells (CAR-T)' where source_pmid = '38266761' and evidence_summary = 'Real cohort of 449 patients treated with commercial CAR-T (CD19, BCMA): 3.6% developed a secondary malignancy at a median follow-up of 10.3 months; projected 5-year cumulative incidence of 15.2% (solid) and 2.3% (hematologic). Only 1 case of T-cell lymphoma effectively linked to the CAR (low transgene levels, pre-existing clone before infusion) -- authors'' conclusion: low risk of T-cell lymphoma attributable to CAR-T itself.';

update known_safe_harbors set tissue_context = 'Real patient case (T cells), phase 1 clinical trial' where source_pmid = '33974080' and evidence_summary = 'REAL CLINICAL CASE, phase 1 trial: 2 patients developed lymphoma derived from CAR-modified T cells using the piggyBac transposon system (untargeted integration). Analysis of the first lymphoma: elevated transgene copy number, BUT no insertion in typical oncogenes -- the malignancy correlated more with copy number and unrelated structural genomic alterations than with the insertion site itself. The transgene promoter activated transcription of surrounding regions despite insulator sequences. One patient died.';
