update known_safe_harbors set tissue_context = 'Human CD4+ T cells' where source_pmid = '26755332' and evidence_summary = 'Direct comparison of 4 systems in human CD4+ T cells: the Sleeping Beauty (SB) transposon showed the distribution closest to true randomness -- "highest theoretical probability of hitting a safe-harbor locus by chance" of the 4 systems. piggyBac and MLV retrovirus showed unexpectedly similar patterns to each other, enriched near transcription start sites, colocalizing with BRD4-associated sites -- a convergent "tethering" mechanism that preferentially directs them toward active genes (riskier).';
update public_safe_harbors_staging set tissue_context = 'Human CD4+ T cells' where source_pmid = '26755332' and evidence_summary = 'Direct comparison of 4 systems in human CD4+ T cells: the Sleeping Beauty (SB) transposon showed the distribution closest to true randomness -- "highest theoretical probability of hitting a safe-harbor locus by chance" of the 4 systems. piggyBac and MLV retrovirus showed unexpectedly similar patterns to each other, enriched near transcription start sites, colocalizing with BRD4-associated sites -- a convergent "tethering" mechanism that preferentially directs them toward active genes (riskier).';

update known_safe_harbors set tissue_context = 'Cell lines and primary human fibroblasts/keratinocytes' where source_pmid = '21468003' and evidence_summary = 'Hybrid HIV-1/SB100X vector: integration up to 160x above background in cell lines and in primary human fibroblasts/keratinocytes. Lentiviral integrations showed a strong bias toward actively transcribed genes; in contrast, SB100X-mediated integrations from the same vector were far more gene-random -- confirms the safer profile of SB100X vs. conventional lentiviral integration.';
update public_safe_harbors_staging set tissue_context = 'Cell lines and primary human fibroblasts/keratinocytes' where source_pmid = '21468003' and evidence_summary = 'Hybrid HIV-1/SB100X vector: integration up to 160x above background in cell lines and in primary human fibroblasts/keratinocytes. Lentiviral integrations showed a strong bias toward actively transcribed genes; in contrast, SB100X-mediated integrations from the same vector were far more gene-random -- confirms the safer profile of SB100X vs. conventional lentiviral integration.';

update known_safe_harbors set tissue_context = 'Real patient cohort (10 patients), hematopoietic stem cells -- historical SCID-X1 gene therapy trial' where source_pmid = '18688286' and evidence_summary = 'THE FOUNDING CASE of the entire safe-harbor field: gene therapy trial for SCID-X1 (10 patients). A gammaretroviral vector integrated 35kb upstream of the LMO2 proto-oncogene, in antisense orientation, causing LMO2 overexpression in the leukemic clone. Leukemogenesis also required additional acquired mutations (NOTCH1 gain-of-function, CDKN2A deletion, TCR-beta/STIL-TAL1 translocation) -- it was not the insertion alone, but the insertion was the initial trigger. This is the historical incident that justifies the existence of this entire safe-harbor catalog.';
